    let mut i = 0
    while get(&s, i) != None {
        i = i + 1
    }
    i
}

fn get(s: &Str, i: Int) -> Option<Str> {
    if i < 0 || i >= str_len(s) {
        None
    } else {
        Some(chars(s).get(i))
    }
}

fn chars(s: &Str) -> Vec<Str> {
    let v = vec()
    for c in s {
        v = push(v, c)
    }
    v
}

