    for c in s {
        putchar(c)
    }
}

fn putchar(x: Char) {
    if x < 0 {
        print("?")
    } else if x < 128 {
        unsafe_wrap_char(x)
    } else {
        print("?")
    }
}

fn unsafe_wrap_char(x: Int) {
    let mut v = vec()
    v = push(v, x)
    v = push(v, 0)
    unsafe_wrap_str(v)
}

fn unsafe_wrap_str(v: Vec<Int>) {
    let v = clone(&v)
    unsafe_unwrap_str(v)
}

fn unsafe_unwrap_str(v: Vec<Int>) {
    let mut i = 0
    while get(&v, i) != Some(0) {
        putchar(get(&v, i).unwrap())
        i = i + 1
    }
}

